def tagged_non_english(name):
    for tag in re.findall(r"\[([^\[\]]+)\]|\(([^()]+)\)", str(name)):
        value = (tag[0] or tag[1]).strip().casefold()
        if value in NON_ENGLISH:
            return True
        # A regional language tag is meaningful only when its base is a known code.
        base, separator, region = value.replace("_", "-").partition("-")
        if separator and len(base) in (2, 3) and base in NON_ENGLISH and region.isalpha():
            return True
    return False
